const items = $input.all();
const results = [];

items.forEach(item => {
  try {
    const output = item.json.output;

    // Clean markdown code blocks
    let cleaned = output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    const parsed = JSON.parse(cleaned);

    // Generate timestamp-based ID
    const now = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    const id = `IDEA-${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}`;

    results.push({
      json: {
        ID: id,
        "Date Added": `${pad(now.getDate())}/${pad(now.getMonth()+1)}/${now.getFullYear()}`,
        "Content Type": parsed.content_type || '',
        "Finding": parsed.finding || '',
        "Source URL": parsed.source_url || '',
        "Relevance": parsed.relevance || '',
        "Status": "New"
      }
    });

  } catch (error) {
    results.push({
      json: {
        error: error.message,
        raw: item.json.output
      }
    });
  }
});

return results;

